<script setup>
    import { onMounted } from 'vue';
import store from '../../store';
import post from '../../utils/post';
    import TransactionsTable from './components/TransactionsTable.vue';
    onMounted(async () => {
        if(store.state.opened){
            const res = await post('TransactionHistory');
            if(res && !store.state.initial.TransactionHistory){
                store.state.initial.TransactionHistory = res;
            }
        }
    });
</script>

<template>
    <div class="transactions">
        <p>Transações</p>
        <div class="transactions-frame">
            <TransactionsTable />
        </div>
    </div>
</template>

